def lvl(P):
    a, b, c, d = P['L']; f = lambda x: '\\(%s\\)' % x
    ex = '%s+%s+%s' % (ov(a, b), ov(b, c), ov(c, d))
    o1 = M4(1, 'Simplify \\(%s\\).' % ex, 'Rút gọn \\(%s\\).' % ex, f(ov(a, d)), [f(ov(a, c)), f(ov(d, a)), f(ov(b, d))], 'Triangle rule: \\(%s\\).' % ov(a, d), 'Quy tắc ba điểm: \\(%s\\).' % ov(a, d))
    (p, s1), (q, s2) = P['op']; v = tuple(s1 * x + s2 * y for x, y in zip(sub(PGM, *p), sub(PGM, *q))); pairs = [(x, y) for x in 'ABCD' for y in 'ABCD' if x != y]
    cc = next(x for x in pairs if sub(PGM, *x) == v); ww = [x for x in pairs if sub(PGM, *x) != v and x != cc][:3]
    sg = '+' if s2 > 0 else '-'; e2 = '%s %s %s' % (ov(*p), sg, ov(*q))
    o2 = M4(2, 'ABCD is a parallelogram. \\(%s=\\)…' % e2, 'ABCD là hình bình hành. \\(%s=\\)…' % e2, f(ov(*cc)), [f(ov(*w)) for w in ww], 'Use the parallelogram rule and equal opposite sides.', 'Dùng quy tắc hình bình hành và các cạnh đối bằng nhau.')
    pp, qq, h = P['py']; o3 = M4(3, 'ABCD is a rectangle with AB = %d and AD = %d. \\(|%s-%s|=\\)…' % (pp, qq, ov('A', 'B'), ov('A', 'D')), 'ABCD là hình chữ nhật có AB = %d, AD = %d. \\(|%s-%s|=\\)…' % (pp, qq, ov('A', 'B'), ov('A', 'D')), str(h), [str(pp + qq), str(abs(pp - qq)), str(h + 1)], '\\(\\overrightarrow{AB}-\\overrightarrow{AD}=\\overrightarrow{DB}\\), a diagonal.', '\\(\\overrightarrow{AB}-\\overrightarrow{AD}=\\overrightarrow{DB}\\), là một đường chéo.')
    u, w = P['t4']; t4 = tf(4, 'In a parallelogram ABCD, \\(%s=%s\\).' % (u, w), 'Trong hình bình hành ABCD, \\(%s=%s\\).' % (u, w), P['v4'], 'Check with the parallelogram rule.', 'Kiểm tra bằng quy tắc hình bình hành.')
    g = P['t5']; t5 = tf(5, 'For a regular hexagon ABCDEF with centre O: \\(%s+%s=%s\\).' % (ov('O', g[0]), ov('O', g[1]), ov('O', g[2])), 'Với lục giác đều ABCDEF tâm O: \\(%s+%s=%s\\).' % (ov('O', g[0]), ov('O', g[1]), ov('O', g[2])), tuple(x + y for x, y in zip(sub(HEX, 'O', g[0]), sub(HEX, 'O', g[1]))) == sub(HEX, 'O', g[2]), 'The sum of two such vectors is the diagonal of a rhombus.', 'Tổng hai vectơ đó là đường chéo của hình thoi dựng trên chúng.')
    k = P['k']; s6 = sh(6, 'Two forces of %d N and %d N act at one point at a right angle. Find the resultant force (in N).' % (P['py'][0] * k, P['py'][1] * k), 'Hai lực %d N và %d N tác dụng tại một điểm, vuông góc với nhau. Tìm độ lớn hợp lực (đơn vị N).' % (P['py'][0] * k, P['py'][1] * k), P['py'][2] * k, 'Diagonal of the rectangle of forces.', 'Đường chéo của hình chữ nhật lực.')
    A_, B_ = P['sq']; s7 = sh(7, 'ABCD is a square with side %d. Find \\(|%s+%s|^2\\).' % (A_, ov('A', 'B'), ov('A', 'D')), 'ABCD là hình vuông cạnh %d. Tính \\(|%s+%s|^2\\).' % (A_, ov('A', 'B'), ov('A', 'D')), 2 * A_ * A_, '\\(\\overrightarrow{AB}+\\overrightarrow{AD}=\\overrightarrow{AC}\\), \\(AC^2=2a^2\\).', '\\(\\overrightarrow{AB}+\\overrightarrow{AD}=\\overrightarrow{AC}\\), \\(AC^2=2a^2\\).')
    return [[o1, o2, o3], [t4, t5], [s6, s7]]
PP = [dict(L='MNPQ', op=((('A', 'B'), 1), (('A', 'D'), 1)), py=(6, 8, 10), t4=('\\overrightarrow{AB}+\\overrightarrow{AD}', '\\overrightarrow{AC}'), v4=True, t5=('A', 'C', 'B'), k=1, sq=(3, 0)),
      dict(L='RSTU', op=((('A', 'C'), 1), (('A', 'B'), -1)), py=(5, 12, 13), t4=('\\overrightarrow{AB}+\\overrightarrow{AD}', '\\overrightarrow{BD}'), v4=False, t5=('B', 'D', 'C'), k=2, sq=(5, 0)),
      dict(L='EFGH', op=((('D', 'B'), 1), (('D', 'A'), -1)), py=(8, 15, 17), t4=('\\overrightarrow{AC}-\\overrightarrow{AD}', '\\overrightarrow{DC}'), v4=True, t5=('A', 'D', 'C'), k=3, sq=(7, 0))]
